private BigDecimal tinhTongTien(Order order) {
    if (order.getItems() == null) return BigDecimal.ZERO;
    return order.getItems().stream()
            .map(i -> i.getPrice().multiply(BigDecimal.valueOf(i.getQuantity())))
            .reduce(BigDecimal.ZERO, BigDecimal::add);
}

private LocalDate layNgayThanhToan(Order order) {
    return order.getStatus() == Status.PAID && order.getPaidAt() != null
            ? order.getPaidAt().toLocalDate()
            : null;
}
