@Repository
@RequiredArgsConstructor
public class ProductJdbcRepository {

    private final JdbcTemplate jdbcTemplate;

    /** RowMapper<T> là functional interface — dùng lambda */
    private static final RowMapper<Product> MAPPER = (rs, rowNum) -> {
        Product p = new Product();
        p.setId(rs.getLong("id"));
        p.setName(rs.getString("name"));
        p.setPrice(rs.getBigDecimal("price"));      // ⭐ BigDecimal cho tiền
        return p;
    };

    public List<Product> findAll() {
        return jdbcTemplate.query("select id, name, price from products", MAPPER);
    }

    public Optional<Product> findById(Long id) {
        List<Product> list = jdbcTemplate.query(
                "select id, name, price from products where id = ?", MAPPER, id);
        return list.stream().findFirst();           // ⭐ Optional, không null
    }
}
